def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
    else:
        whole, frac = s, ""

    if "." in frac:
        raise ValueError("malformed amount")

    whole = whole or "0"
    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("malformed amount")

    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)
    if negative:
        cents = -cents

    return str(cents)

