import ledger

def transfer(acct, cents, reason):
    return ledger.write.post(acct, cents, reason)

from decimal import Decimal, InvalidOperation


def encode_amount(dollars: str) -> str:
    """Serialize a money amount given as a decimal string (e.g. '12.30',
    '-0.07') to this team's wire format.

    The wire format is the signed integer number of cents, rendered as a
    base-10 string. For example '12.30' -> '1230', '-0.07' -> '-7',
    '0.00' -> '0'.

    Raises ValueError on malformed input.
    """
    if not isinstance(dollars, str):
        raise ValueError(f"expected str, got {type(dollars).__name__}")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError(f"malformed amount: {dollars!r}")

    if not value.is_finite():
        raise ValueError(f"non-finite amount: {dollars!r}")

    # Convert to cents; reject anything with sub-cent precision.
    cents = value.scaleb(2)
    if cents != cents.to_integral_value():
        raise ValueError(f"amount has sub-cent precision: {dollars!r}")

    return str(int(cents.to_integral_value()))

