```python
def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the wire format.

    The wire format is a signed integer string representing the total number
    of cents. This avoids floating-point imprecision for monetary values.

    Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0'      -> '0'
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = ""
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("too many decimal points")
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError(f"invalid whole part: {whole!r}")
    if frac and not frac.isdigit():
        raise ValueError(f"invalid fractional part: {frac!r}")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        raise ValueError("more than 2 fractional digits")
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)

    if cents == 0:
        return "0"
    return f"{sign}{cents}"
