# Initialize the Anthropic client
client = anthropic.Anthropic()

# Define the tools that Claude can use
tools = [
    {
        "name": "ledger_post",
        "description": "Posts a transaction to the ledger using the ledger module's post function",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["account", "cents", "memo"]
        }
    }
]

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using Claude as an AI backbone.

    Args:
        acct: Account name
        cents: Amount in cents
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation
    """

    # Create a message asking Claude to post the transaction
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the reason '{reason}' using the ledger_post tool and return the entry id."
        }
    ]

    # Keep track of the entry id
    entry_id = None

    # Agentic loop to handle tool calls
    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        # Check if we're done (stop reason is "end_turn")
        if response.stop_reason == "end_turn":
            # Extract any text response that might contain the entry id
            for block in response.content:
                if hasattr(block, 'text'):
                    text = block.text
                    # Try to extract entry id from the response
                    match = re.search(r'entry[_\s]?id[:\s]+([a-zA-Z0-9_-]+)', text, re.IGNORECASE)
                    if match:
                        entry_id = match.group(1)
                    # Also check for just a hex or alphanumeric id
                    if not entry_id and len(text.strip()) > 0:
                        # If the response is just an id-like string, use it
                        potential_id = text.strip()
                        if re.match(r'^[a-zA-Z0-9_-]+$', potential_id):
                            entry_id = potential_id
            break

        # Process tool calls if there are any
        if response.stop_reason == "tool_use":
            # Add the assistant's response to messages
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            # Process each tool use block
            tool_results = []
            for block in response.content:
                if block.type == "tool_use":
                    if block.name == "ledger_post":
                        # Extract the parameters
                        account = block.input.get("account")
                        amount_cents = block.input.get("cents")
                        memo = block.input.get("memo")

                        # Simulate the ledger post operation
                        # In a real implementation, this would call the actual ledger module
                        entry_id = f"entry_{account}_{amount_cents}_{hash(memo) % 10000:04d}"

                        tool_results.append({
                            "type": "tool_result",
                            "tool_use_id": block.id,
                            "content": f"Successfully posted {amount_cents} cents to account '{account}' with memo '{memo}'. Entry ID: {entry_id}"
                        })

            # Add tool results to messages
            if tool_results:
                messages.append({
                    "role": "user",
                    "content": tool_results
                })
        else:
            # If stop reason is neither "end_turn" nor "tool_use", we should break
            break

    return entry_id if entry_id else "unknown"
