            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if not tool_use_block:
            break

        if tool_use_block.name == "post":
            input_data = tool_use_block.input
            account = input_data.get("account", acct)
            amount = input_data.get("amount", cents)
            memo = input_data.get("memo", reason)

            entry_id = f"{account}_{amount}_{memo}"
            entry_id = entry_id.replace(" ", "_").replace(":", "").lower()
            entry_id = re.sub(r'[^a-z0-9_]', '', entry_id)

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": json.dumps({"entry_id": entry_id, "status": "success"})
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )
        else:
            break

    for block in response.content:
        if hasattr(block, 'text'):
            text = block.text
            if 'entry_id' in text.lower():
                lines = text.split('\n')
                for line in lines:
                    if 'entry_id' in line.lower():
                        parts = line.split(':')
                        if len(parts) > 1:
                            return parts[1].strip().strip('"').strip("'")

    return f"{acct}_{cents}_{reason}".replace(" ", "_").replace(":", "").lower()

