        if hasattr(block, 'text'):
            # Try to extract entry id from the response
            text = block.text
            if "entry_" in text:
                # Simple extraction of entry id pattern
                import re
                match = re.search(r'entry_\d+', text)
                if match:
                    return match.group(0)

    # Fallback: try to get it from the last tool result
    if response.stop_reason == "end_turn":
        # Look back through messages for the tool result
        for i in range(len(messages) - 1, -1, -1):
            if isinstance(messages[i].get("content"), list):
                for content_block in messages[i]["content"]:
                    if isinstance(content_block, dict) and content_block.get("type") == "tool_result":
                        import json
                        result = json.loads(content_block.get("content", "{}"))
                        if isinstance(result, dict) and "entry_id" in result:
                            return result["entry_id"]

    return None

if __name__ == "__main__":
    # Test the transfer function
