def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the
    team's private wire format.

    The wire format encodes the amount as a signed integer number of cents,
    rendered as a string. Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0.00'   -> '0'
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in '+-':
        negative = s[0] == '-'
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if '.' in s:
        whole, _, frac = s.partition('.')
    else:
        whole, frac = s, ''

    if '.' in frac:
        raise ValueError("too many decimal points")

    whole = whole or '0'
    if not whole.isdigit():
        raise ValueError("invalid integer part")
    if frac and not frac.isdigit():
        raise ValueError("invalid fractional part")

    # Normalize fractional part to exactly two digits (cents).
    if len(frac) > 2:
        # Round half-up based on the third digit.
        cents_str = frac[:2]
        round_digit = frac[2]
        cents = int(cents_str)
        if round_digit >= '5':
            cents += 1
    else:
        cents = int((frac + '00')[:2])

    total_cents = int(whole) * 100 + cents

    if negative:
        total_cents = -total_cents

    return str(total_cents)

