def encode_amount(dollars: str) -> str:
    sign = ""
    if dollars.startswith("-"):
        sign = "-"
        dollars = dollars[1:]

    if "." in dollars:
        int_part, frac_part = dollars.split(".", 1)
    else:
        int_part = dollars
        frac_part = "00"

    if len(frac_part) == 1:
        frac_part = frac_part + "0"
    elif len(frac_part) == 0:
        frac_part = "00"
    elif len(frac_part) > 2:
        raise ValueError(f"Too many fractional digits: {dollars}")

    if not int_part:
        int_part = "0"

    int_digits = int_part.lstrip("0") or "0"
    return f"{sign}{int_digits}.{frac_part}"

