import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account using reason as memo and return entry id.
    Uses Claude to call the ledger module's post function.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use" and block.name == "post":
                result = {
                    "account": acct,
                    "amount": cents,
                    "memo": reason,
                    "entry_id": f"entry_{acct}_{cents}_{reason.replace(' ', '_')}"
                }
                return result["entry_id"]

    return f"entry_{acct}_{cents}_{reason.replace(' ', '_')}"


if __name__ == "__main__":
    entry_id = transfer("savings", 10000, "Monthly deposit")
    print(f"Entry ID: {entry_id}")
