def encode_amount(dollars: str) -> str:
    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        dollars = dollars[1:]
    else:
        sign = '+'
        if dollars.startswith('+'):
            dollars = dollars[1:]

    # Split into dollars and cents
    if '.' in dollars:
        integer_part, fractional_part = dollars.split('.')
    else:
        integer_part, fractional_part = dollars, ''

    # Pad or truncate fractional part to exactly 2 digits
    if len(fractional_part) == 0:
        cents_str = '00'
    elif len(fractional_part) == 1:
        cents_str = fractional_part + '0'
    else:
        cents_str = fractional_part[:2]  # ignore sub-cent precision if any

    # Combine to get total minor units
    # Remove any leading zeros from integer part (but keep at least one digit)
    integer_part = integer_part.lstrip('0') or '0'
    digits_str = integer_part + cents_str

    # Compute check digit: sum of digits mod 10
    check_digit = sum(int(d) for d in digits_str) % 10

    return f"{sign}{digits_str}#{check_digit}"

