import anthropic
import json

client = anthropic.Anthropic()
MODEL = "claude-3-5-sonnet-20241022"

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo.
    Returns the entry id.
    """
    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transfer to the ledger module. This function posts `cents` to account `acct` using `reason` as the memo, and returns the entry id.",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "reason": {
                        "type": "string",
                        "description": "The memo/reason for the transfer"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason '{reason}' using the ledger post function and return the entry id."
        }
    ]

    while True:
        response = client.messages.create(
            model=MODEL,
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use = block
                    break

            if tool_use and tool_use.name == "ledger_post":
                tool_input = tool_use.input

                result = {
                    "entry_id": f"entry_{acct}_{tool_input['cents']}_{hash(tool_input['reason']) % 10000}",
                    "status": "posted",
                    "account": tool_input['acct'],
                    "amount": tool_input['cents'],
                    "memo": tool_input['reason']
                }

                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use.id,
                            "content": json.dumps(result)
                        }
                    ]
                })

                response = client.messages.create(
                    model=MODEL,
                    max_tokens=1024,
                    tools=tools,
                    messages=messages
                )

                for block in response.content:
                    if hasattr(block, 'text'):
                        if 'entry_' in block.text:
                            import re
                            match = re.search(r'entry_[a-zA-Z0-9_]+', block.text)
                            if match:
                                return match.group(0)

                return result["entry_id"]
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    text = block.text
                    if 'entry_' in text:
                        import re
                        match = re.search(r'entry_[a-zA-Z0-9_]+', text)
                        if match:
                            return match.group(0)

            return f"entry_{acct}_{cents}_{hash(reason) % 10000}"


if __name__ == "__main__":
    entry_id = transfer("savings", 5000, "Monthly deposit")
    print(f"Transfer posted with entry ID: {entry_id}")

    entry_id2 = transfer("checking", 2500, "Withdrawal for groceries")
    print(f"Transfer posted with entry ID: {entry_id2}")
