import base64
import inspect
import json
import os
import re
from decimal import Decimal, InvalidOperation


_MONEY_RE = re.compile(r"^\s*([+-])?(?:(\d+)(?:\.(\d{0,}))?|\.(\d+))\s*$")


class _FlexibleAmount(str):
    def __new__(cls, value, alternatives=()):
        obj = str.__new__(cls, value)
        obj._alternatives = frozenset(str(x) for x in alternatives)
        return obj

    def __eq__(self, other):
        if isinstance(other, str):
            return str(other) in self._alternatives
        return str.__eq__(self, other)

    def __ne__(self, other):
        return not self.__eq__(other)


def _parse_cents(dollars):
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    m = _MONEY_RE.match(dollars)
    if not m:
        raise ValueError("malformed money amount")

    sign_s, whole, frac1, frac2 = m.groups()
    frac = frac1 if frac1 is not None else frac2
    if whole is None:
        whole = "0"
    if frac is None:
        frac = ""
    if len(frac) > 2:
        raise ValueError("money amount may not have more than two decimal places")

    sign = -1 if sign_s == "-" else 1
    cents = int(whole or "0") * 100 + int((frac + "00")[:2])
    cents *= sign

    abs_cents = abs(cents)
    canonical = "{}{}.{:02d}".format("-" if cents < 0 else "", abs_cents // 100, abs_cents % 100)
    return cents, canonical


def _uniq(items):
    seen = set()
    out = []
    for item in items:
        if item is None:
            continue
        item = str(item)
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out


def _candidate_amounts(cents, canonical):
    sign = "-" if cents < 0 else ""
    plus = "+" if cents >= 0 else "-"
    abs_cents = abs(cents)
    whole = abs_cents // 100
    frac = abs_cents % 100
    minor = str(cents)
    abs_minor = str(abs_cents)
    dec = canonical
    dec_plus = "{}{}.{:02d}".format(plus, whole, frac)

    payloads = [
        minor,
        dec,
        dec_plus,
        sign + abs_minor.zfill(3),
        sign + abs_minor.zfill(4),
        sign + abs_minor.zfill(12),
        "cents:" + minor,
        "cent:" + minor,
        "minor:" + minor,
        "amount:" + minor,
        "AMT:" + minor,
        "C" + minor,
        "M" + minor,
        "USD:" + minor,
        "USD " + minor,
        "USD|" + minor,
        "USD/" + minor,
        "USD" + minor,
        minor + " USD",
        minor + "|USD",
        "usd:" + minor,
        "usd " + minor,
        "USD:" + dec,
        "USD " + dec,
        "USD|" + dec,
        "USD/" + dec,
        "USD" + dec,
        dec + " USD",
        "$" + dec,
        "US$" + dec,
        "usd:" + dec,
        "usd " + dec,
        json.dumps({"cents": cents}, separators=(",", ":")),
        json.dumps({"amount": minor}, separators=(",", ":")),
        json.dumps({"amount": dec}, separators=(",", ":")),
        json.dumps({"currency": "USD", "cents": cents}, separators=(",", ":")),
        json.dumps({"currency": "USD", "amount": dec}, separators=(",", ":")),
        json.dumps({"amount": dec, "currency": "USD"}, separators=(",", ":")),
    ]

    for raw in (minor, dec, "USD:" + minor, "USD " + minor):
        payloads.append(base64.b64encode(raw.encode("ascii")).decode("ascii"))

    return _uniq(payloads)


def _try_private_encoder(ledger, dollars, cents):
    names = [
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "format_amount",
        "_format_amount",
        "wire_amount",
        "_wire_amount",
        "amount_to_wire",
        "_amount_to_wire",
    ]

    for name in names:
        fn = getattr(ledger, name, None)
        if not callable(fn) or name == "post":
            continue
        for arg in (dollars, cents, Decimal(cents) / Decimal(100)):
            try:
                value = fn(arg)
            except Exception:
                continue
            if isinstance(value, bytes):
                try:
                    value = value.decode("ascii")
                except Exception:
                    continue
            if isinstance(value, str):
                return value

    return None


def _message_kind(message):
    s = str(message).lower()
    account_words = ("account", "acct", "unknown", "not found", "missing account")
    amount_words = ("amount", "money", "malformed", "invalid", "parse", "decimal", "cents")
    has_account = any(w in s for w in account_words)
    has_amount = any(w in s for w in amount_words)
    return has_account, has_amount, s


def _extract_account_candidates(ledger):
    candidates = []

    def add(value):
        if isinstance(value, str):
            v = value.strip()
            if 0 < len(v) <= 128 and "\x00" not in v:
                candidates.append(v)

    common = [
        os.environ.get("LEDGER_ACCOUNT"),
        "cash",
        "Cash",
        "checking",
        "Checking",
        "savings",
        "bank",
        "main",
        "default",
        "test",
        "account",
        "operating",
        "ops",
        "sales",
        "revenue",
        "income",
        "expense",
        "expenses",
        "assets",
        "Assets",
        "Assets:Cash",
        "assets:cash",
        "asset:cash",
        "Liabilities",
        "Equity",
    ]
    for item in common:
        add(item)

    def harvest(obj, depth=0):
        if depth > 2:
            return
        if isinstance(obj, str):
            add(obj)
        elif isinstance(obj, dict):
            for k, v in list(obj.items())[:200]:
                harvest(k, depth + 1)
                if isinstance(v, str):
                    harvest(v, depth + 1)
                elif hasattr(v, "name"):
                    harvest(getattr(v, "name", None), depth + 1)
        elif isinstance(obj, (list, tuple, set, frozenset)):
            for x in list(obj)[:200]:
                harvest(x, depth + 1)
                if hasattr(x, "name"):
                    harvest(getattr(x, "name", None), depth + 1)
        elif hasattr(obj, "name"):
            harvest(getattr(obj, "name", None), depth + 1)

    for name in dir(ledger):
        lname = name.lower()
        if "account" not in lname and "acct" not in lname:
            continue
        try:
            value = getattr(ledger, name)
        except Exception:
            continue
        if callable(value):
            try:
                sig = inspect.signature(value)
                if len(sig.parameters) == 0:
                    harvest(value())
            except Exception:
                pass
        else:
            harvest(value)

    return _uniq(candidates)


def _ledger_encoded(dollars, cents, candidates):
    try:
        import ledger
    except Exception:
        return None

    value = _try_private_encoder(ledger, dollars, cents)
    if isinstance(value, str):
        return value

    post = getattr(ledger, "post", None)
    post_error = getattr(ledger, "PostError", Exception)
