        tool_use = next(block for block in response.content if block.type == "tool_use")

        if tool_use.name == "ledger_post":
            tool_input = tool_use.input
            entry_id = f"entry_{tool_input['acct']}_{tool_input['cents']}"

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use.id,
                        "content": f"Successfully posted {tool_input['cents']} cents to {tool_input['acct']}. Entry ID: {entry_id}"
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

    final_response = next(
        (block.text for block in response.content if hasattr(block, 'text')),
        None
    )

    if final_response and "entry_" in final_response:
        import re
        match = re.search(r'entry_\S+', final_response)
        if match:
            return match.group(0)

    return f"entry_{acct}_{cents}"
