# Initialize the Anthropic client (uses ANTHROPIC_API_KEY by default)
client = anthropic.Anthropic()

# Define the ledger tools
tools = [
    {
        "name": "ledger_post",
        "description": "Post a transaction to the ledger. Posts cents to account acct with the given reason as memo. Returns the entry id.",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "reason": {
                    "type": "string",
                    "description": "The reason/memo for the transaction"
                }
            },
            "required": ["acct", "cents", "reason"]
        }
    }
]

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account acct using reason as the memo.
    Returns the entry id from the ledger.
    """
    # Create a message to ask Claude to post the transaction
    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account '{acct}' with reason '{reason}'. Use the ledger_post tool and return the entry id."
        }
    ]

    # Call Claude with tools
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    entry_id = None

    # Check if we need to handle tool use
    if response.stop_reason == "tool_use":
        for content in response.content:
            if content.type == "tool_use":
                # Simulate the ledger_post function
                tool_input = content.input
                # In a real scenario, this would call the actual ledger module
                # For now, we'll return a mock entry id
                entry_id = f"entry_{tool_input['acct']}_{tool_input['cents']}"

                # Continue the conversation with the tool result
                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": content.id,
                            "content": entry_id
                        }
                    ]
                })

                # Get final response
                final_response = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=1024,
                    tools=tools,
                    messages=messages
                )

                # Extract entry id from final response
                for final_content in final_response.content:
                    if hasattr(final_content, 'text'):
                        # Try to extract entry id from the response
                        if "entry_" in final_content.text:
                            # Extract the entry id from the text
                            import re
                            match = re.search(r'entry_\S+', final_content.text)
                            if match:
                                return match.group(0)

    # If we couldn't extract from Claude, return our generated entry id
    if entry_id:
        return entry_id

    # Fallback: return a default entry id
    return f"entry_{acct}_{cents}"


if __name__ == "__main__":
    # Test the transfer function
    result = transfer("checking", 10000, "Monthly salary deposit")
    print(f"Transfer result: {result}")
