# solution.py

def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to the team's private wire format.

    The wire format is: integer cents (positive or negative) as a string,
    with no decimal point and no leading zeros except for zero itself.
    """
    # Parse the decimal string into integer cents
    if '.' in dollars:
        integer_part, fractional_part = dollars.split('.', 1)
    else:
        integer_part, fractional_part = dollars, ''

    # Validate and pad fractional part to exactly 2 digits
    if len(fractional_part) == 0:
        fractional_part = '00'
    elif len(fractional_part) == 1:
        fractional_part = fractional_part + '0'
    elif len(fractional_part) > 2:
        raise ValueError("Amount must have at most 2 decimal places")

    sign = ''
    if integer_part.startswith('-'):
        sign = '-'
        integer_part = integer_part[1:]

    # Remove leading zeros from integer part, but keep at least one digit
    integer_part = integer_part.lstrip('0') or '0'

    # Combine into cents
    cents_str = f"{integer_part}{fractional_part}"
    cents = int(cents_str)

    if sign == '-':
        cents = -cents

    return str(cents)

