    if '.' not in s:
        dollars_part = s
        cents_part = '00'
    else:
        dollars_part, cents_part = s.split('.', 1)
        if len(cents_part) == 1:
            cents_part += '0'
        elif len(cents_part) == 0:
            cents_part = '00'
        elif len(cents_part) > 2:
