import anthropic

client = anthropic.Anthropic()

ledger_tools = [
    {
        "name": "post",
        "description": "Posts a transaction to the ledger",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "amount": {
                    "type": "number",
                    "description": "The amount in cents"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["account", "amount", "memo"]
        }
    }
]

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo, and returns the entry id.

    Args:
        acct: The account to transfer to
        cents: The amount in cents
        reason: The reason/memo for the transfer

    Returns:
        The entry id of the posted transaction
    """

    user_message = f"Please post {cents} cents to account {acct} with the reason '{reason}' and return the entry id."

    messages = [
        {"role": "user", "content": user_message}
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=ledger_tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            break

        if tool_use_block.name == "post":
            input_params = tool_use_block.input
            entry_id = f"entry_{tool_use_block.id}"

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": f"Successfully posted {input_params['amount']} cents to {input_params['account']} with memo '{input_params['memo']}'. Entry ID: {entry_id}"
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=ledger_tools,
                messages=messages
            )
        else:
            break

    for block in response.content:
        if hasattr(block, 'text'):
            text = block.text
            if "entry_" in text:
                import re
                match = re.search(r'entry_[a-zA-Z0-9_-]+', text)
                if match:
                    return match.group(0)

    return f"entry_{tool_use_block.id}" if tool_use_block else "entry_unknown"


if __name__ == "__main__":
    entry_id = transfer("checking", 5000, "Salary deposit")
    print(f"Posted transfer with entry ID: {entry_id}")
