def encode_amount(dollars: str) -> str:
    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        numeric_part = dollars[1:]
    else:
        sign = '+'
        numeric_part = dollars

    # Parse dollars and cents
    if '.' in numeric_part:
        whole, cents = numeric_part.split('.', 1)
    else:
        whole, cents = numeric_part, ''

    # Normalize cents to exactly two digits
    if len(cents) == 0:
        cents = '00'
    elif len(cents) == 1:
        cents = cents + '0'
    elif len(cents) > 2:
        # Truncate extra fractional digits beyond cents
        cents = cents[:2]

    # Remove leading zeros from whole part, but keep at least one digit
    whole = whole.lstrip('0')
    if whole == '':
        whole = '0'

    # Combine into minor units string
    digits = whole + cents

    # Compute check digit: sum of decimal digits mod 10
    check = sum(int(d) for d in digits) % 10

    return f"{sign}{digits}#{check}"

