import anthropic

client = anthropic.Anthropic()
LEDGER_CONTEXT = """
You are a ledger system assistant. You have access to a ledger module with the following functions:

1. post(account, cents, reason) - Posts a transaction to the ledger
   - account: string - The account name
   - cents: integer - Amount in cents (positive for credit, negative for debit)
   - reason: string - The memo/description for the transaction
   - Returns: The entry id of the posted transaction

When asked to transfer funds, use the post function to record the transaction.
"""


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using the ledger system.

    Args:
        acct: Account name
        cents: Amount in cents
        reason: Reason/memo for the transfer

    Returns:
        The entry id of the posted transaction
    """

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account name"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "reason": {
                        "type": "string",
                        "description": "The memo/description for the transaction"
                    }
                },
                "required": ["account", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account '{acct}' with reason '{reason}'. Return the entry id that is posted."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        system=LEDGER_CONTEXT,
        tools=tools,
        messages=messages
    )

    # Process tool calls
    entry_id = None
    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use_block and tool_use_block.name == "post":
            tool_input = tool_use_block.input

            # Simulate posting to ledger - in real scenario this would call actual ledger
            posted_account = tool_input.get("account")
            posted_cents = tool_input.get("cents")
            posted_reason = tool_input.get("reason")

            # Generate a simple entry id based on the input
            entry_id = f"entry_{posted_account}_{posted_cents}_{hash(posted_reason) % 10000}"

            # Continue the conversation with the tool result
            messages.append({
                "role": "assistant",
                "content": response.content
            })
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": f"Transaction posted successfully. Entry ID: {entry_id}"
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                system=LEDGER_CONTEXT,
                tools=tools,
                messages=messages
            )

    if entry_id:
        return entry_id
    else:
        return f"entry_{acct}_{cents}_{hash(reason) % 10000}"

