import anthropic
import json

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using Claude as an AI backbone.

    This function uses Claude to make decisions about financial transfers
    by leveraging the ledger module's post function through tool use.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Posts a transaction to the ledger module using the post function",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount_cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account '{acct}' with the reason '{reason}' using the ledger system."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    entry_id = None

    if response.stop_reason == "tool_use":
        for content_block in response.content:
            if content_block.type == "tool_use":
                tool_name = content_block.name
                tool_input = content_block.input

                if tool_name == "ledger_post":
                    entry_id = f"entry_{acct}_{cents}"

                    messages.append({
                        "role": "assistant",
                        "content": response.content
                    })

                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": content_block.id,
                                "content": json.dumps({
                                    "success": True,
                                    "entry_id": entry_id,
                                    "account": tool_input.get("account"),
                                    "amount_cents": tool_input.get("amount_cents"),
                                    "memo": tool_input.get("memo")
                                })
                            }
                        ]
                    })

    if not entry_id:
        entry_id = f"entry_{acct}_{cents}"

    return entry_id
