"""encode_amount converts a USD amount string ('12.30', '-0.07')
into the module's private wire format for posting to the ledger.
"""


def encode_amount(dollars: str) -> str:
    """Serialize a money amount to the team's private wire format."""
    # Strip leading/trailing whitespace
    s = dollars.strip()

    # Determine sign
    sign = ""
    if s.startswith("-"):
        sign = "-"
        s = s[1:]
    elif s.startswith("+"):
        s = s[1:]  # explicit positive, strip the '+'

    if not s:
        raise ValueError("empty amount after sign strip")

    # Split on optional decimal point
    if "." in s:
        integer_part, fractional_part = s.split(".", 1)
    else:
        integer_part, fractional_part = s, ""

    # Validate that both parts are purely digits (or empty)
    if integer_part == "":
        integer_part = "0"
    if not integer_part.isdigit():
        raise ValueError(f"invalid integer part: {integer_part!r}")
    if fractional_part and not fractional_part.isdigit():
        raise ValueError(f"invalid fractional part: {fractional_part!r}")

    # Pad/truncate fractional part to exactly 2 digits
    if len(fractional_part) > 2:
        fractional_part = fractional_part[:2]
    else:
        fractional_part = fractional_part.ljust(2, "0")

    # Remove leading zeros from integer part (but keep at least one digit)
    integer_part = integer_part.lstrip("0") or "0"

    wire_amount = f"{sign}{integer_part}.{fractional_part}"

    # ledger.post raises PostError on unknown account or malformed amount;
    # here we just serialize to the expected canonical decimal format (two decimal places,
    # no unnecessary leading zeros, minus sign for negative).
    return wire_amount

