    sign = '+'
    if s.startswith('-'):
        sign = '-'
        s = s[1:]
    elif s.startswith('+'):
        s = s[1:]

    # Remove optional currency symbol
    if s.startswith('$'):
        s = s[1:]

    # Split into whole and fractional parts
    if '.' in s:
        whole, frac = s.split('.', 1)
    else:
        whole, frac = s, ''

    # Normalize whole part
    if not whole:
        whole = '0'

    # Normalize fractional part to exactly 2 digits
    if len(frac) == 0:
        frac = '00'
    elif len(frac) == 1:
        frac = frac + '0'
    else:
        frac = frac[:2]

    # Combine and convert to integer to strip leading zeros
    cents = int(whole + frac)
    digits = str(cents)

    # Compute Luhn-style check digit: sum of digits mod 10
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

