def encode_amount(dollars: str) -> str:
    """Serialize a money amount to the team's private wire format."""
    if '.' not in dollars:
        raise ValueError("Amount must include a decimal point")

    integer_part, fractional_part = dollars.split('.', 1)

    if len(fractional_part) != 2:
        raise ValueError("Amount must have exactly two decimal places")

    sign = ''
    if integer_part.startswith('-'):
        sign = '-'
        integer_part = integer_part[1:]

    if not integer_part:
        integer_part = '0'

    integer_part = integer_part.lstrip('0') or '0'

    encoded = f"{sign}{integer_part}.{fractional_part}"
    return encoded

