import anthropic

client = anthropic.Anthropic()

def post(acct: str, cents: int, reason: str) -> str:
    """Posts a transaction to an account using Claude as an AI backbone."""

    tools = [
        {
            "name": "transfer",
            "description": "Transfer money to an account",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to transfer to"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "The amount in cents to transfer"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transfer"
                    }
                },
                "required": ["account", "amount_cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please transfer {cents} cents to account {acct} with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use":
                if block.name == "transfer":
                    entry_id = f"entry_{hash(str(block.input)) % 10000000}"
                    return entry_id

    return ""
