def _encode_amount(cents):
    sign = "-" if cents < 0 else "+"
    digits = str(abs(cents))
    check = sum(int(d) for d in digits) % 10
    return f"{sign}{digits}#{check}"


def transfer(acct, cents, reason):
    return ledger.post(acct, _encode_amount(cents), memo=reason)

def encode_amount(dollars: str) -> str:
    """
    Encodes a money amount string to the team's private wire format.

    The wire format represents amounts as cents (integers) to avoid floating point issues.
    For example:
    - '12.30' -> '1230' (1230 cents)
    - '-0.07' -> '-7' (-7 cents)
    - '0' -> '0'
    """
    # Remove any whitespace
    dollars = dollars.strip()

    # Handle empty string
    if not dollars:
        raise ValueError("Amount cannot be empty")

    # Split on decimal point
    if '.' in dollars:
        parts = dollars.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid amount format")

        integer_part, decimal_part = parts

        # Handle sign
        is_negative = integer_part.startswith('-')
        if is_negative:
            integer_part = integer_part[1:]

        # Validate integer part
        if not integer_part:
            integer_part = '0'
        if not integer_part.isdigit():
            raise ValueError("Invalid amount format")

        # Validate and pad decimal part to 2 digits
        if not decimal_part:
            raise ValueError("Invalid amount format")
        if not decimal_part.isdigit():
            raise ValueError("Invalid amount format")
        if len(decimal_part) > 2:
            raise ValueError("Amount has too many decimal places")

        # Pad decimal to 2 digits
        decimal_part = decimal_part.ljust(2, '0')

        # Combine to get cents
        cents_str = integer_part + decimal_part
        cents = int(cents_str)

        if is_negative:
            cents = -cents

        return str(cents)
    else:
        # No decimal point - treat as whole dollars
        if not dollars or (dollars.startswith('-') and len(dollars) == 1):
            raise ValueError("Invalid amount format")

        # Validate it's a number
        try:
            amount = int(dollars)
        except ValueError:
            raise ValueError("Invalid amount format")

        # Convert dollars to cents
        cents = amount * 100
        return str(cents)

