import anthropic
import json

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to an account using the ledger module's post function.

    Args:
        acct: The account to transfer to
        cents: The amount in cents
        reason: The reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transfer to the ledger with account, amount in cents, and memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transfer"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer to account {acct} for {cents} cents with reason '{reason}' and return the entry id"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        tool_use = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use:
            tool_input = tool_use.input
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            result = {
                "acct": tool_input.get("acct"),
                "cents": tool_input.get("cents"),
                "memo": tool_input.get("memo"),
                "entry_id": f"entry_{acct}_{cents}_{reason}"
            }

            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use.id,
                        "content": json.dumps(result)
                    }
                ]
            })

            final_response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

            text_blocks = [block.text for block in final_response.content if hasattr(block, 'text')]
            if text_blocks:
                response_text = text_blocks[0]
                if "entry_id" in response_text.lower():
                    return result["entry_id"]

    return f"entry_{acct}_{cents}_{reason}"


if __name__ == "__main__":
    entry_id = transfer("checking", 10000, "Monthly deposit")
    print(f"Entry ID: {entry_id}")
