        raise ValueError(f"amount must be finite: {dollars!r}")

    # Convert to integer cents, rounding is disallowed: reject >2 decimal places.
    cents = (value * 100)
    if cents != cents.to_integral_value():
        raise ValueError(f"amount has sub-cent precision: {dollars!r}")

    return _format_wire(int(cents))


def _format_wire(cents: int) -> str:
    return str(cents)

