def transfer(acct, cents, reason):
    try:
        entry_id = ledger.post(acct, cents, memo=reason)
    except ledger.PostError:
        raise
    return entry_id

def encode_amount(dollars: str) -> str:
    s = dollars.replace('$', '').strip()
    if s.startswith('-'):
        sign = '-'
        s = s[1:]
    else:
        sign = '+'
        if s.startswith('+'):
            s = s[1:]

    if '.' in s:
        whole, frac = s.split('.', 1)
    else:
        whole, frac = s, ''

    whole = whole.lstrip('0')
