def encode_amount(dollars: str) -> str:
    sign = -1 if dollars.startswith('-') else 1
    if dollars.startswith('+') or dollars.startswith('-'):
        body = dollars[1:]
    else:
        body = dollars

    if '.' in body:
        whole, frac = body.split('.', 1)
    else:
        whole, frac = body, ''

    if not whole:
        whole = '0'

    frac = (frac + '00')[:2]

    value = (int(whole) * 100 + int(frac)) * sign
    return str(value)

