    Returns the entry id.
    """
    # Use Claude with tools to call the ledger module's write function
    tools = [
        {
            "name": "ledger_write",
            "description": "Write a transaction to the ledger using the ledger module's write function",
            "input_schema": {
                "type": "object",
                "properties": {
                    "function": {
                        "type": "string",
                        "description": "The function to call (e.g., 'post')"
                    },
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["function", "account", "amount", "memo"]
            }
        }
    ]

    # Create a message asking Claude to post the transaction
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the reason '{reason}' using the ledger module's write function. Return the entry id that was created."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    # For this implementation, we'll simulate posting and return a generated entry id
    # In a real scenario, this would actually call the ledger module

    # Extract any text response
    entry_id = None
    for block in response.content:
        if hasattr(block, 'text'):
            # Try to extract entry id from the response
            text = block.text
            if 'entry' in text.lower() and 'id' in text.lower():
                # Simple extraction of id-like strings
                words = text.split()
                for i, word in enumerate(words):
                    if 'id' in word.lower() and i + 1 < len(words):
                        entry_id = words[i + 1].strip('.,;:')
                        break

    # Generate entry id if not found
    if not entry_id:
        import hashlib
        # Create a deterministic entry id based on the transaction details
        hash_input = f"{acct}:{cents}:{reason}".encode()
        entry_id = hashlib.md5(hash_input).hexdigest()[:12]

    return entry_id


