                        break

    # Generate entry id if not found
    if not entry_id:
        import hashlib
        # Create a deterministic entry id based on the transaction details
        hash_input = f"{acct}:{cents}:{reason}".encode()
        entry_id = hashlib.md5(hash_input).hexdigest()[:12]

    return entry_id


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account acct using reason as the memo.
    Returns the entry id created by the ledger post function.
    """
    return post(acct, cents, reason)


if __name__ == "__main__":
    # Test the transfer function
    entry_id = transfer("savings", 10000, "Monthly deposit")
    print(f"Created entry: {entry_id}")

