            "name": "ledger_post",
            "description": "Post a transaction to the ledger using the ledger module's post function",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account '{acct}' with reason '{reason}' using the ledger post function. Return the entry id."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
