                    return entry_id
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    text = block.text
                    if "entry" in text.lower() or "id" in text.lower():
                        import re
                        match = re.search(r'([a-zA-Z0-9\-]+)', text)
                        if match:
                            return match.group(1)

            return ""
