import ledger

def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise ledger.PostError("malformed amount")

    body = dollars
    sign = ""
    if body.startswith("-"):
        sign = "-"
        body = body[1:]

    parts = body.split(".")
    if len(parts) != 2:
        raise ledger.PostError("malformed amount")

    whole, cents = parts
    if not whole.isdigit() or not cents.isdigit() or len(cents) != 2:
        raise ledger.PostError("malformed amount")

    combined = (whole + cents).lstrip("0")
    if not combined:
        combined = "0"
    if combined == "0":
        sign = ""

    return sign + combined

