import re

_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$")


def _raise_malformed(message: str):
    try:
        import ledger
        exc_type = getattr(ledger, "PostError", ValueError)
    except Exception:
        exc_type = ValueError

    try:
        raise exc_type(message)
    except TypeError:
        raise exc_type()


def encode_amount(dollars: str) -> str:
    """
    Encode a decimal dollar amount as signed integer cents.

    Examples:
        '12.30' -> '1230'
        '-0.07' -> '-7'
    """
    if not isinstance(dollars, str):
        _raise_malformed("amount must be a string")

    match = _AMOUNT_RE.fullmatch(dollars)
    if not match:
        _raise_malformed("malformed amount")

    sign, whole, frac1, frac2 = match.groups()
    whole = whole or "0"
    frac = frac1 if frac1 is not None else frac2
    frac = (frac or "").ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    if sign == "-" and cents:
        cents = -cents

    return str(cents)

