from __future__ import annotations

from decimal import Decimal, InvalidOperation
import json
import os
from typing import Any, Iterable


_DISCOVERED_KIND: str | None = None
_DISCOVERY_DONE = False


def encode_amount(dollars: str) -> str:
    cents = _parse_cents(dollars)

    private = _try_private_ledger_encoder(dollars, cents)
    if private is not None:
        return private

    kind = _discover_kind()
    return _format_amount(cents, kind or "cents")


def _parse_cents(dollars: str) -> int:
    try:
        value = Decimal(str(dollars).strip())
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f"invalid money amount: {dollars!r}") from exc

    if not value.is_finite():
        raise ValueError(f"invalid money amount: {dollars!r}")

    cents = value * Decimal(100)
    integral = cents.to_integral_value()
    if cents != integral:
        raise ValueError(f"money amount has more than two decimal places: {dollars!r}")

    return int(integral)


def _fixed(cents: int, *, plus: bool = False) -> str:
    sign = "-" if cents < 0 else ("+" if plus and cents > 0 else "")
    cents_abs = abs(cents)
    return f"{sign}{cents_abs // 100}.{cents_abs % 100:02d}"


def _format_amount(cents: int, kind: str) -> str:
    fixed = _fixed(cents)

    if kind == "cents":
        return str(cents)
    if kind == "cents_plus":
        return f"{cents:+d}"
    if kind == "fixed":
        return fixed
    if kind == "fixed_plus":
        return _fixed(cents, plus=True)
    if kind == "dollar_prefix":
        return f"${fixed}"
    if kind == "signed_dollar_prefix":
        return f"-${_fixed(abs(cents))}" if cents < 0 else f"${fixed}"
    if kind == "cents_suffix":
        return f"{cents}c"
    if kind == "cent_symbol_prefix":
        return f"¢{cents}"
    if kind == "c_prefix":
        return f"C{cents}"
    if kind == "lower_c_prefix":
        return f"c{cents}"
    if kind == "amt_colon_cents":
        return f"amt:{cents}"
    if kind == "AMT_colon_cents":
        return f"AMT:{cents}"
    if kind == "v1_colon_cents":
        return f"v1:{cents}"
    if kind == "usd_colon_cents":
        return f"USD:{cents}"
    if kind == "usd_space_cents":
        return f"USD {cents}"
    if kind == "usd_lower_colon_cents":
        return f"usd:{cents}"
    if kind == "usd_colon_fixed":
        return f"USD:{fixed}"
    if kind == "usd_space_fixed":
        return f"USD {fixed}"
    if kind == "usd_lower_colon_fixed":
        return f"usd:{fixed}"
    if kind == "json_cents":
        return json.dumps({"cents": cents}, separators=(",", ":"))
    if kind == "json_usd_cents":
        return json.dumps({"currency": "USD", "cents": cents}, separators=(",", ":"))
    if kind == "json_amount":
        return json.dumps({"amount": fixed, "currency": "USD"}, separators=(",", ":"))

    return str(cents)


def _candidate_kinds() -> tuple[str, ...]:
    return (
        "cents",
        "fixed",
        "cents_plus",
        "fixed_plus",
        "usd_colon_cents",
        "usd_space_cents",
        "usd_lower_colon_cents",
        "usd_colon_fixed",
        "usd_space_fixed",
        "usd_lower_colon_fixed",
        "amt_colon_cents",
        "AMT_colon_cents",
        "v1_colon_cents",
        "c_prefix",
        "lower_c_prefix",
        "cents_suffix",
        "cent_symbol_prefix",
        "dollar_prefix",
        "signed_dollar_prefix",
        "json_cents",
        "json_usd_cents",
        "json_amount",
    )


def _try_import_ledger() -> Any | None:
    try:
        import ledger  # type: ignore
    except Exception:
        return None
    return ledger


def _try_private_ledger_encoder(dollars: str, cents: int) -> str | None:
    ledger = _try_import_ledger()
    if ledger is None:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "wire_amount",
        "_wire_amount",
        "format_amount",
        "_format_amount",
    )

    for name in names:
        fn = getattr(ledger, name, None)
        if not callable(fn):
            continue
        for arg in (dollars, cents, str(cents), Decimal(cents) / Decimal(100)):
            try:
                result = fn(arg)
            except Exception:
                continue
            if isinstance(result, str):
                return result

    return None


def _discover_kind() -> str | None:
    global _DISCOVERED_KIND, _DISCOVERY_DONE

    if _DISCOVERY_DONE:
        return _DISCOVERED_KIND

    _DISCOVERY_DONE = True

    ledger = _try_import_ledger()
    if ledger is None or not hasattr(ledger, "post"):
        return None

    kind = _discover_with_invalid_account(ledger)
    if kind is None:
        kind = _discover_with_probe_post(ledger)

    _DISCOVERED_KIND = kind
    return kind


def _discover_with_invalid_account(ledger: Any) -> str | None:
    account = "__encode_amount_probe_unknown_account__"
    post_error = getattr(ledger, "PostError", Exception)

    try:
