from decimal import Decimal, InvalidOperation

def encode_amount(dollars: str) -> str:
    s = dollars.strip().replace("$", "")

    sign = "+"
    if s.startswith("-"):
        sign = "-"
        s = s[1:]
    elif s.startswith("+"):
        s = s[1:]

    if not s:
        raise ValueError("Invalid amount")

    try:
        value = Decimal(s)
    except InvalidOperation:
        raise ValueError("Invalid amount")

    cents = int(value * 100)

    if cents < 0:
        sign = "-"
        abs_cents = -cents
    else:
        sign = "+"
        abs_cents = cents

    digits = str(abs_cents)
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

