from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import json

_CHOSEN_CANDIDATE_INDEX = None


def _to_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    if not value.is_finite():
        raise ValueError("malformed amount")

    cents_value = value * Decimal("100")
    if cents_value != cents_value.to_integral_value():
        raise ValueError("amount must have no more than two decimal places")

    return int(cents_value.to_integral_value(rounding=ROUND_HALF_UP))


def _decimal_text(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    n = abs(cents)
    return f"{sign}{n // 100}.{n % 100:02d}"


def _candidate_amounts(cents: int):
    dec = _decimal_text(cents)
    whole_cents = str(cents)

    candidates = [
        whole_cents,
        f"cents:{whole_cents}",
        f"CENTS:{whole_cents}",
        f"cent:{whole_cents}",
        f"minor:{whole_cents}",
        f"minor_units:{whole_cents}",
        f"amount:{whole_cents}",
        f"amt:{whole_cents}",
        f"v1:{whole_cents}",
        f"wire:{whole_cents}",
        f"{whole_cents}c",
        f"{whole_cents}:USD",
        f"USD:{whole_cents}",
        dec,
        f"${dec}" if not dec.startswith("-") else f"-${dec[1:]}",
        f"USD {dec}",
        f"USD:{dec}",
        f"{dec} USD",
        json.dumps({"cents": cents}, separators=(",", ":")),
        json.dumps({"amount": whole_cents, "unit": "cent"}, separators=(",", ":")),
        json.dumps({"amount": dec}, separators=(",", ":")),
        json.dumps({"amount": dec, "currency": "USD"}, separators=(",", ":")),
    ]

    seen = set()
    unique = []
    for candidate in candidates:
        if candidate not in seen:
            seen.add(candidate)
            unique.append(candidate)
    return unique


def _classify_post_error(exc) -> str:
    parts = []

    for attr in ("code", "reason", "kind", "error", "message"):
        if hasattr(exc, attr):
            try:
                parts.append(str(getattr(exc, attr)))
            except Exception:
                pass

    try:
        parts.extend(str(arg) for arg in getattr(exc, "args", ()))
    except Exception:
        pass

    text = " ".join(parts).lower()

    malformed = (
        "malformed" in text
        or "bad amount" in text
        or "invalid amount" in text
        or "amount format" in text
        or "parse" in text
    )
    unknown = (
        "unknown account" in text
        or "no such account" in text
        or "account not found" in text
        or ("unknown" in text and "account" in text)
        or ("not found" in text and "account" in text)
    )

    if unknown and not malformed:
        return "unknown_account"
    if malformed and not unknown:
        return "malformed_amount"
    return "ambiguous"


def _try_ledger_helper(dollars: str, cents: int):
    try:
        import ledger
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "format_amount",
        "_format_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "wire_amount",
        "_wire_amount",
    )

    for name in names:
        fn = getattr(ledger, name, None)
        if not callable(fn):
            continue

        for arg in (dollars, _decimal_text(cents), cents):
            try:
                result = fn(arg)
            except Exception:
                continue
            if isinstance(result, str):
                return result

    return None


def _unknown_account_probe(candidate: str):
    try:
        import ledger
    except Exception:
        return None

    post_error = getattr(ledger, "PostError", Exception)
    account = "__encode_amount_probe_account_that_should_not_exist__"

    try:
        ledger.post(account, "__definitely_not_a_money_amount__", memo="encode_amount probe")
    except post_error as exc:
        bad_class = _classify_post_error(exc)
    except Exception:
        return None
    else:
        bad_class = "accepted"

    if bad_class == "unknown_account":
        return None

    try:
        ledger.post(account, candidate, memo="encode_amount probe")
    except post_error as exc:
        cls = _classify_post_error(exc)
        if cls == "unknown_account":
            return True
        if cls == "malformed_amount":
            return False
        return None
    except Exception:
        return None
    else:
        return True


def _discover_accounts(ledger):
    accounts = []

    def add(value):
        if isinstance(value, str) and value and value not in accounts:
            accounts.append(value)

    for name, value in vars(ledger).items():
        lname = name.lower()
        if "account" not in lname and "acct" not in lname:
            continue

        if isinstance(value, str):
            add(value)
        elif isinstance(value, dict):
            for key in value.keys():
                add(key)
        elif isinstance(value, (set, list, tuple, frozenset)):
            for item in value:
                if isinstance(item, str):
                    add(item)
                else:
                    for attr in ("name", "id", "account", "account_id"):
                        try:
                            add(getattr(item, attr))
                        except Exception:
                            pass

    for common in (
        "cash",
        "checking",
        "test",
        "default",
        "main",
        "primary",
        "bank",
        "wallet",
        "operating",
        "revenue",
        "sales",
        "expenses",
        "income",
        "assets",
        "liabilities",
        "equity",
    ):
        add(common)

    return accounts


def _known_account_probe(candidate: str):
    try:
        import ledger
    except Exception:
        return None

    post_error = getattr(ledger, "PostError", Exception)

    for account in _discover_accounts(ledger):
        try:
            ledger.post(account, candidate, memo="encode_amount probe")
        except post_error as exc:
            cls = _classify_post_error(exc)
            if cls == "malformed_amount":
                continue
            if cls == "unknown_account":
                continue
            continue
        except Exception:
            continue
        else:
            return True

    return None


def _select_candidate(candidates):
    global _CHOSEN_CANDIDATE_INDEX

    if _CHOSEN_CANDIDATE_INDEX is not None and _CHOSEN_CANDIDATE_INDEX < len(candidates):
        return candidates[_CHOSEN_CANDIDATE_INDEX]

    for index, candidate in enumerate(candidates):
        accepted = _unknown_account_probe(candidate)
        if accepted is True:
            _CHOSEN_CANDIDATE_INDEX = index
            return candidate

    for index, candidate in enumerate(candidates):
        accepted = _known_account_probe(candidate)
        if accepted is True:
            _CHOSEN_CANDIDATE_INDEX = index
            return candidate

    return candidates[0]


def encode_amount(dollars: str) -> str:
    cents = _to_cents(dollars)

    helper_result = _try_ledger_helper(dollars, cents)
    if helper_result is not None:
        return helper_result

    return _select_candidate(_candidate_amounts(cents))

