)


def _raise_post_error(message: str) -> None:
    exc_type = PostError
    try:
        import ledger  # type: ignore
    except Exception:
        pass
    else:
        exc_type = getattr(ledger, "PostError", PostError)

    try:
        raise exc_type(message)
    except TypeError:
        raise exc_type()


