    whole_text = match.group("whole") or "0"
    frac_text = match.group("frac") if match.group("frac") is not None else match.group("onlyfrac")
    frac_text = (frac_text or "").ljust(2, "0")

    cents = int(whole_text) * 100 + int(frac_text)
    if sign == "-" and cents != 0:
