def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    saw_sign = False

    if s[0] in "+-":
        sign = s[0]
        saw_sign = True
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if s and s[0] in "+-":
        if saw_sign:
            raise ValueError("multiple signs")
        sign = s[0]
        s = s[1:].strip()

    if not s:
        raise ValueError("missing amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError("invalid dollar component")

    if frac and not frac.isdigit():
        raise ValueError("invalid cent component")

    if len(frac) > 2:
        if any(ch != "0" for ch in frac[2:]):
            raise ValueError("amount has more than two decimal places")
        frac = frac[:2]

    frac = frac.ljust(2, "0")
    digits = (whole + frac).lstrip("0") or "0"
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

