def encode_amount(dollars: str) -> str:
    s = dollars.strip()

    if s.startswith("-"):
        sign = "-"
        s = s[1:]
    else:
        sign = "+"
        if s.startswith("+"):
            s = s[1:]

    if s.startswith("$"):
        s = s[1:]

    if "." in s:
        whole, frac = s.split(".", 1)
        if not whole:
            whole = "0"
        # Keep at most two fractional digits, pad with zero on the right.
        frac = (frac + "00")[:2]
        minor = int(whole) * 100 + int(frac)
    else:
        minor = int(s) * 100

    digits = str(minor)
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

