def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("amount must be a string")

    negative = False
    if dollars.startswith("-"):
        negative = True
        rest = dollars[1:]
    elif dollars.startswith("+"):
        rest = dollars[1:]
    else:
        rest = dollars

    if not rest or rest == ".":
        raise ValueError("malformed amount")

    if rest.count(".") > 1:
        raise ValueError("malformed amount")

    if "." in rest:
        whole, frac = rest.split(".")
        if len(frac) > 2:
            raise ValueError("too many decimal places")
        frac = frac.ljust(2, "0")
    else:
        whole = rest
        frac = "00"

    if not whole:
        whole = "0"

    if not whole.isdigit() or not frac.isdigit():
        raise ValueError("malformed amount")

    cents = int(whole) * 100 + int(frac)
    return str(-cents if negative else cents)

