from decimal import Decimal, InvalidOperation
import json
import base64
import inspect
import re

_selected_encoder = None


def _parse_cents(dollars: str) -> int:
    try:
        value = Decimal(str(dollars).strip())
    except (InvalidOperation, AttributeError):
        raise ValueError("malformed dollar amount")

    cents = value * Decimal(100)
    integral = cents.to_integral_value()
    if cents != integral:
        raise ValueError("amount must have no more than two decimal places")
    return int(integral)


def _decimal_text(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _candidate_encoders():
    def cents(c):
        return str(c)

    def decimal(c):
        return _decimal_text(c)

    encoders = [cents]

    prefixes = [
        "cents", "cent", "CENTS", "minor", "amount", "amt", "AMT",
        "money", "MONEY", "wire", "ledger", "LEDGER", "v1", "V1",
        "usd", "USD", "USDc", "USD¢", "dollars", "DOLLARS",
        "money/v1", "ledger/v1", "amount/v1",
    ]

    for p in prefixes:
        encoders.append(lambda c, p=p: f"{p}:{c}")
        encoders.append(lambda c, p=p: f"{p}|{c}")
        encoders.append(lambda c, p=p: f"{p} {c}")

    encoders.extend([
        lambda c: f"${_decimal_text(c)}",
        lambda c: f"USD:{_decimal_text(c)}",
        lambda c: f"USD|{_decimal_text(c)}",
        lambda c: f"USD {_decimal_text(c)}",
        lambda c: f"usd:{_decimal_text(c)}",
        lambda c: f"amount:{_decimal_text(c)}",
        lambda c: f"amt:{_decimal_text(c)}",
        lambda c: f"money:{_decimal_text(c)}",
        lambda c: f"v1:{_decimal_text(c)}",
        lambda c: f"LEDGER:{_decimal_text(c)}",
        lambda c: f"AMT:{_decimal_text(c)}",
        lambda c: f"A:{c}",
        lambda c: f"M:{c}",
        lambda c: f"#{c}",
        lambda c: f"{c}c",
        lambda c: f"{c} cents",
        lambda c: f"{c}:USD",
        lambda c: f"{c}|USD",
        lambda c: f"+{c}" if c >= 0 else str(c),
        lambda c: ("P" if c >= 0 else "N") + str(abs(c)),
        lambda c: ("p:" if c >= 0 else "n:") + str(abs(c)),
        lambda c: ("+" if c >= 0 else "-") + f"{abs(c):012d}",
        lambda c: ("+" if c >= 0 else "-") + f"{abs(c):016d}",
        lambda c: f"{abs(c):012d}" if c >= 0 else "-" + f"{abs(c):012d}",
        lambda c: f"{abs(c):016d}" if c >= 0 else "-" + f"{abs(c):016d}",
        lambda c: hex(c),
        lambda c: json.dumps({"cents": c}, separators=(",", ":")),
        lambda c: json.dumps({"amount": c}, separators=(",", ":")),
        lambda c: json.dumps({"amount": str(c)}, separators=(",", ":")),
        lambda c: json.dumps({"amount": _decimal_text(c)}, separators=(",", ":")),
        lambda c: json.dumps({"dollars": _decimal_text(c)}, separators=(",", ":")),
        lambda c: json.dumps({"currency": "USD", "cents": c}, separators=(",", ":")),
        lambda c: base64.b64encode(str(c).encode("ascii")).decode("ascii"),
    ])

    encoders.append(decimal)
    return encoders


def _walk_strings(obj, seen=None, depth=0):
    if seen is None:
        seen = set()
    if depth > 3:
        return set()

    oid = id(obj)
    if oid in seen:
        return set()
    seen.add(oid)

    out = set()
    if isinstance(obj, str):
        if 0 < len(obj) <= 80:
            out.add(obj)
    elif isinstance(obj, dict):
        for k, v in list(obj.items())[:300]:
            out |= _walk_strings(k, seen, depth + 1)
            out |= _walk_strings(v, seen, depth + 1)
    elif isinstance(obj, (list, tuple, set, frozenset)):
        for item in list(obj)[:300]:
            out |= _walk_strings(item, seen, depth + 1)
    return out


def _code_strings(func):
    out = set()
    try:
        code = func.__code__
    except AttributeError:
        return out

    def visit(co):
        for const in co.co_consts:
            if isinstance(const, str) and 0 < len(const) <= 80:
                out.add(const)
            elif inspect.iscode(const):
                visit(const)

    visit(code)
    return out


def _ledger_strings(ledger):
    out = set()
    for value in vars(ledger).values():
        out |= _walk_strings(value)
        if callable(value):
            out |= _code_strings(value)
    return out


def _candidate_accounts(ledger):
    common = [
        "cash", "bank", "checking", "main", "default", "test", "tests",
        "sales", "revenue", "income", "expense", "expenses", "asset",
        "assets", "liability", "equity", "receivables", "payables",
        "accounts:cash", "assets:cash", "income:sales", "ledger",
        "account", "acct", "A", "test-account",
    ]

    found = []
    for name, value in vars(ledger).items():
        lname = name.lower()
        strings = _walk_strings(value)
        if "account" in lname or "acct" in lname:
            found.extend(strings)
        elif isinstance(value, dict):
            found.extend(k for k in value.keys() if isinstance(k, str))
        elif isinstance(value, (set, list, tuple)):
            found.extend(x for x in value if isinstance(x, str))

    found.extend(_ledger_strings(ledger))
    found.extend(common)

    seen = set()
    accounts = []
    for item in found:
        if isinstance(item, str) and 0 < len(item) <= 80 and item not in seen:
            seen.add(item)
            accounts.append(item)
    return accounts


def _snap_ledger(ledger):
    snap = []
    for name, value in vars(ledger).items():
        try:
            if isinstance(value, dict):
                snap.append(("dict", name, value, value.copy()))
            elif isinstance(value, list):
                snap.append(("list", name, value, list(value)))
            elif isinstance(value, set):
                snap.append(("set", name, value, set(value)))
            elif isinstance(value, (int, str)) and any(x in name.lower() for x in ("id", "seq", "next", "count")):
                snap.append(("attr", name, None, value))
        except Exception:
            pass
    return snap


def _restore_ledger(ledger, snap):
    for kind, name, obj, old in reversed(snap):
        try:
            if kind == "dict":
                obj.clear()
                obj.update(old)
            elif kind == "list":
                obj[:] = old
            elif kind == "set":
                obj.clear()
                obj.update(old)
            elif kind == "attr":
                setattr(ledger, name, old)
        except Exception:
            pass


def _extra_encoders_from_ledger(ledger):
    strings = _ledger_strings(ledger)
    extras = []

    clean = []
    for s in strings:
        if 0 < len(s) <= 24 and not any(ch in s for ch in "\n\r\t{}[]"):
            clean.append(s)

    for s in clean[:200]:
        extras.extend([
            lambda c, s=s: f"{s}{c}",
            lambda c, s=s: f"{s}:{c}",
            lambda c, s=s: f"{s}|{c}",
            lambda c, s=s: f"{s} {c}",
            lambda c, s=s: f"{c}{s}",
            lambda c, s=s: f"{s}{_decimal_text(c)}",
            lambda c, s=s: f"{s}:{_decimal_text(c)}",
            lambda c, s=s: f"{s}|{_decimal_text(c)}",
            lambda c, s=s: f"{s} {_decimal_text(c)}",
        ])

    for s in strings:
        if "{cents}" in s or "{amount}" in s or "{minor}" in s:
            extras.append(lambda c, s=s: s.format(cents=c, amount=c, minor=c, dollars=_decimal_text(c)))
        if "%d" in s:
            extras.append(lambda c, s=s: s % c)

    return extras


def _try_post(ledger, account, amount):
    snap = _snap_ledger(ledger)
    try:
        entry_id = ledger.post(account, amount, memo="encode_amount probe")
        return isinstance(entry_id, int) and entry_id >= 1
    except getattr(ledger, "PostError", Exception):
        return False
    finally:
        _restore_ledger(ledger, snap)


def _discover_encoder():
    try:
        import ledger
    except Exception:
        return None

    accounts = _candidate_accounts(ledger)
    if not accounts:
        return None

    encoders = _candidate_encoders() + _extra_encoders_from_ledger(ledger)

    seen_amounts = set()
    ordered = []
    for enc in encoders:
        try:
            probe = enc(0)
        except Exception:
            continue
        if isinstance(probe, str) and probe not in seen_amounts:
            seen_amounts.add(probe)
            ordered.append(enc)

    for probe_cents in (0, 1, -1, 123):
        for enc in ordered:
            try:
                amount = enc(probe_cents)
            except Exception:
                continue
            if not isinstance(amount, str):
                continue
            for account in accounts:
                if _try_post(ledger, account, amount):
                    return enc

    return None


def encode_amount(dollars: str) -> str:
    global _selected_encoder

    cents = _parse_cents(dollars)

    if _selected_encoder is None:
        _selected_encoder = _discover_encoder()
        if _selected_encoder is None:
            _selected_encoder = lambda c: str(c)

    return _selected_encoder(cents)

