def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    sign_seen = False

    if s[0] in "+-":
        sign = s[0]
        sign_seen = True
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if s and s[0] in "+-":
        if sign_seen:
            raise ValueError("multiple signs")
        sign = s[0]
        s = s[1:].strip()

    s = s.replace(",", "")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("amount has more than two decimal places")

