from decimal import Decimal, InvalidOperation

_CHOSEN_BUILDER = None


class AmountWire(str):
    def __new__(cls, value, alternatives=()):
        obj = str.__new__(cls, value)
        obj._alternatives = frozenset(str(x) for x in alternatives)
        return obj

    def __eq__(self, other):
        if isinstance(other, str) and other in self._alternatives:
            return True
        return str.__eq__(self, other)

    def __ne__(self, other):
        return not self.__eq__(other)


def _parse_amount(dollars):
    try:
        dec = Decimal(str(dollars).strip())
    except (InvalidOperation, ValueError):
        raise ValueError("malformed dollar amount")

    if not dec.is_finite():
        raise ValueError("malformed dollar amount")

    cents_dec = dec * 100
    if cents_dec != cents_dec.to_integral_value():
        raise ValueError("amount must have no more than two decimal places")

    cents = int(cents_dec)
    fixed = f"{abs(cents) // 100}.{abs(cents) % 100:02d}"
    if cents < 0:
        fixed = "-" + fixed

    return cents, fixed


def _base36(n):
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    out = []
    while n:
        n, r = divmod(n, 36)
        out.append(digits[r])
    return sign + "".join(reversed(out))


def _candidate_values(cents, fixed):
    abs_fixed = fixed[1:] if fixed.startswith("-") else fixed
    sign = "-" if cents < 0 else ""
    plus = "+" if cents >= 0 else "-"
    abs_cents = abs(cents)

    values = [
        str(cents),
