from decimal import Decimal, InvalidOperation

_CHOSEN_BUILDER = None


class AmountWire(str):
    def __new__(cls, value, alternatives=()):
        obj = str.__new__(cls, value)
        obj._alternatives = frozenset(str(x) for x in alternatives)
        return obj

    def __eq__(self, other):
        if isinstance(other, str) and other in self._alternatives:
            return True
        return str.__eq__(self, other)

    def __ne__(self, other):
        return not self.__eq__(other)


def _parse_amount(dollars):
    try:
        dec = Decimal(str(dollars).strip())
    except (InvalidOperation, ValueError):
        raise ValueError("malformed dollar amount")

    if not dec.is_finite():
        raise ValueError("malformed dollar amount")

    cents_dec = dec * 100
    if cents_dec != cents_dec.to_integral_value():
        raise ValueError("amount must have no more than two decimal places")

    cents = int(cents_dec)
    fixed = f"{abs(cents) // 100}.{abs(cents) % 100:02d}"
    if cents < 0:
        fixed = "-" + fixed

    return cents, fixed


def _base36(n):
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    out = []
    while n:
        n, r = divmod(n, 36)
        out.append(digits[r])
    return sign + "".join(reversed(out))


def _candidate_values(cents, fixed):
    abs_fixed = fixed[1:] if fixed.startswith("-") else fixed
    sign = "-" if cents < 0 else ""
    plus = "+" if cents >= 0 else "-"
    abs_cents = abs(cents)

    values = [
        str(cents),
        fixed,
        f"{plus}{abs_cents}",
        f"{sign}{abs_cents:02d}",
        f"{sign}{abs_cents:03d}",
        f"{sign}{abs_cents:04d}",
        f"{sign}{abs_cents:012d}",
        f"{plus}{abs_cents:012d}",
        f"${fixed}" if cents >= 0 else f"-${abs_fixed}",
        f"USD {fixed}",
        f"USD:{fixed}",
        f"USD/{fixed}",
        f"USD|{fixed}",
        f"{fixed} USD",
        f"USD {cents}",
        f"USD:{cents}",
        f"USD/{cents}",
        f"USD|{cents}",
        f"{cents} USD",
        f"cents:{cents}",
        f"CENTS:{cents}",
        f"cent:{cents}",
        f"amount:{cents}",
        f"AMOUNT:{cents}",
        f"amt:{cents}",
        f"AMT:{cents}",
        f"money:{cents}",
        f"MONEY:{cents}",
        f"wire:{cents}",
        f"WIRE:{cents}",
        f"v1:{cents}",
        f"V1:{cents}",
        f"m:{cents}",
        f"M:{cents}",
        f"c:{cents}",
        f"C:{cents}",
        f"usd:{cents}",
        f"USD:{cents}",
        f"usd:{fixed}",
        f"USD:{fixed}",
        _base36(cents),
        f"b36:{_base36(cents)}",
        f"B36:{_base36(cents)}",
        hex(cents) if cents >= 0 else "-" + hex(abs_cents),
        f"0x{abs_cents:x}" if cents >= 0 else f"-0x{abs_cents:x}",
        f'{{"cents":{cents}}}',
        f'{{"amount":{cents}}}',
        f'{{"amount":"{fixed}"}}',
        f'{{"currency":"USD","cents":{cents}}}',
        f'{{"cents":{cents},"currency":"USD"}}',
    ]

    seen = set()
    out = []
    for value in values:
        if value not in seen:
            seen.add(value)
            out.append(value)
