def _try_ledger_helper(dollars, cents, fixed):
    try:
        import ledger
    except Exception:
        return None

    for name in (
        "encode_amount",
        "serialize_amount",
        "amount_to_wire",
        "to_wire_amount",
        "wire_amount",
        "_encode_amount",
        "_serialize_amount",
        "_amount_to_wire",
