        "cash",
        "checking",
        "savings",
        "main",
        "default",
        "primary",
        "test",
        "sandbox",
        "ledger",
        "account",
        "assets:cash",
        "Assets:Cash",
        "bank",
    ]

    def add(value):
        if isinstance(value, str) and value and len(value) <= 128:
            accounts.append(value)

    for name in dir(ledger):
        lname = name.lower()
        if "account" not in lname and "acct" not in lname:
            continue
        try:
            value = getattr(ledger, name)
        except Exception:
            continue

        if isinstance(value, str):
            add(value)
        elif isinstance(value, dict):
            for key, item in list(value.items())[:100]:
                add(key)
                add(item)
