                    add(key)
                    add(item)
            elif isinstance(result, (list, tuple, set, frozenset)):
                for item in list(result)[:100]:
                    add(item)

    seen = set()
    out = []
    for account in accounts:
        if account not in seen:
            seen.add(account)
            out.append(account)
    return out


